typedef unsigned int nslSoundId;

#define MAX_SONGS 50
#define NSL_INVALID_ID 0

class Track
{
  nslSoundId mySrcId;
  nslSoundId mySndId;
  bool paused;
public:
  char songName[30];
  char artistName[30];
  nslSoundId Play();
};

class MusicListing
{
private:
  int               totalSources;
  int               current;
  Track             sources[MAX_SONGS];
  nslSoundId        currentSoundId;
  bool              sucessfulLastPlay;
public:
  nslSoundId  playNext();

  int               order[MAX_SONGS];
  bool              enabled[MAX_SONGS];
};

nslSoundId MusicListing::playNext()
{
  int counter = 0;
  if (sucessfulLastPlay)
    current++;
  if (current >= totalSources)
    current = 0;
  while ((counter < MAX_SONGS) && (!enabled[order[current]]))
  {
    counter++;
    current++;
    if (current >= totalSources)
      current = 0;
  }
  if (!enabled[order[current]])
    return NSL_INVALID_ID;

  if (totalSources > 0)
  {
    currentSoundId = sources[order[current]].Play();
    sucessfulLastPlay = (currentSoundId != NSL_INVALID_ID);
    return currentSoundId;
  }
  else
  {
    currentSoundId = NSL_INVALID_ID;
    return NSL_INVALID_ID;
  }

}
